// Writes (or, with --check, verifies) the golden files of the deterministic construct suite: for every fixture under
// construct-suite/, the type TypeScript 7.1's checker gives prop `p` of the exported `Row`, normalized as src/oracle.ts
// normalizes it. One program holds all fixtures.
import { existsSync, readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { API } from 'typescript-beta/sync'
import { exportName, propsTypeOf } from './checker-components.ts'
import { listFixtures, PROP, type Fixture, type Golden } from './construct-suite.ts'
import { checkerNormalizer } from './oracle-checker.ts'

const suite = realpathSync(join(import.meta.dirname, '..', 'construct-suite'))
const check = process.argv.includes('--check')

const fixtures = listFixtures(suite)
if (fixtures.length === 0) throw new Error(`no fixtures under ${suite}`)

const api = new API({ cwd: suite })
// `parseConfigFile`, not options by hand: the 7.1 beta's server panics on string-valued enum options (src/oracle.ts).
const { options } = api.parseConfigFile(join(suite, 'tsconfig.json'))
const program = api.createProgram(
  fixtures.map((f) => f.file),
  options,
)
const { checker } = program.getProject()
const norm = checkerNormalizer(checker)

function capture(fixture: Fixture): Golden {
  const moduleSymbol = checker.getSymbolOfSourceFile(fixture.file)
  const exported =
    moduleSymbol && checker.getExportsOfModule(moduleSymbol).find((e: any) => exportName(checker, e) === 'Row')
  if (!exported) throw new Error(`${fixture.id}: no exported Row`)
  const propsType = propsTypeOf(checker, exported)
  const prop = propsType && checker.getPropertyOfType(propsType, PROP)
  if (!prop) throw new Error(`${fixture.id}: Row has no prop ${PROP}`)
  const type = checker.getTypeOfSymbol(prop)
  return { checker: norm(type), text: checker.typeToString(type) }
}

const stale: string[] = []
for (const fixture of fixtures) {
  const text = `${JSON.stringify(capture(fixture), null, 2)}\n`
  const current = existsSync(fixture.golden) ? readFileSync(fixture.golden, 'utf8') : undefined
  if (current === text) continue
  stale.push(fixture.id)
  if (!check) writeFileSync(fixture.golden, text)
}
program.dispose()
api.close()

if (check && stale.length > 0) {
  console.error(
    `golden files out of date (run pnpm --filter caliper-docgen-oracle construct:capture):\n  ${stale.join('\n  ')}`,
  )
  process.exit(1)
}
console.error(`${fixtures.length} fixtures, ${stale.length} ${check ? 'differ' : 'written'}`)
// The deterministic construct suite's pure half (apps/oracle/construct-suite/README.md): which fixtures exist, the verdict
// one of Caliper's props earns against its golden, and the check of the expectations file. Nothing here runs the checker
// or Caliper, so tests/construct-suite.test.ts can pin it without either.
import { readdirSync } from 'node:fs'
import { join } from 'node:path'
import { caliperNorm, compare, type Norm, type Verdict } from './oracle-compare.ts'

/** The prop every fixture states its type through. */
export const PROP = 'p'

/** What the suite says about a row: the comparison's verdict, plus the two cases it cannot make. `opaque with marker`
 * is a type Caliper left unevaluated and said so (`degradedBy`); `missing` is a prop Caliper did not list. */
export type RowVerdict = Verdict | 'opaque with marker' | 'missing'

export const GREEN: RowVerdict[] = ['identical', 'spelled']

/** Best to worst. A row whose verdict moved down this list got worse; up, better. `checker any/error` is a fixture
 * problem (the golden has no type), ranked last so it never reads as an improvement. */
export const ORDER: RowVerdict[] = [
  'identical',
  'spelled',
  'opaque with marker',
  'less precise',
  'wrong',
  'missing',
  'checker any/error',
]

/** What `--check` and the test read back from `<name>.golden.json`. */
export interface Golden {
  /** The checker's type of prop `p`, normalized by src/oracle-checker.ts. */
  checker: Norm
  /** `checker.typeToString` of the same type, for the reader of a diff. */
  text: string
}

export interface Fixture {
  /** `<family>/<NN>-<slug>`: the row id the expectations file keys on. */
  id: string
  /** The fixture's absolute path. */
  file: string
  /** The golden's absolute path, next to the fixture. */
  golden: string
}

const FIXTURE = /^\d{2}-[a-z0-9][a-z0-9-]*\.tsx$/

/** Every `<family>/<NN>-<slug>.tsx` under `dir`, sorted by id. A `.tsx` whose name breaks the pattern is an error, not a
 * row that quietly never runs. */
export function listFixtures(dir: string): Fixture[] {
  const fixtures: Fixture[] = []
  for (const family of readdirSync(dir, { withFileTypes: true })) {
    if (!family.isDirectory()) continue
    for (const entry of readdirSync(join(dir, family.name))) {
      if (!entry.endsWith('.tsx')) continue
      if (!FIXTURE.test(entry)) {
        throw new Error(`${family.name}/${entry}: a fixture is named <NN>-<slug>.tsx (lowercase)`)
      }
      const file = join(dir, family.name, entry)
      fixtures.push({
        id: `${family.name}/${entry.replace(/\.tsx$/, '')}`,
        file,
        golden: file.replace(/\.tsx$/, '.golden.json'),
      })
    }
  }
  return fixtures.toSorted((a, b) => (a.id < b.id ? -1 : 1))
}

/** The verdict for Caliper's prop against the golden. A prop with `degradedBy` that is only `less precise` is an
 * `opaque with marker`: Caliper said it did not evaluate the type. A `wrong` prop stays wrong with or without a marker. */
export function rowVerdict(prop: { type: unknown; degradedBy?: unknown } | undefined, golden: Golden): RowVerdict {
  if (prop === undefined) return 'missing'
  const verdict = compare(caliperNorm(prop.type), golden.checker)
  const marked = Array.isArray(prop.degradedBy) && prop.degradedBy.length > 0
  return marked && verdict === 'less precise' ? 'opaque with marker' : verdict
}

export interface Expectation {
  /** The verdicts the row may have; the test fails on any other. */
  verdicts: RowVerdict[]
  /** Why Caliper falls short of the checker here. Present exactly on a documented gap. */
  gap?: string
}

/** Problems with the expectations against the fixtures; empty when they agree. */
export function expectationProblems(ids: string[], rows: Record<string, Expectation>): string[] {
  const problems: string[] = []
  for (const id of ids) {
    const row = rows[id]
    if (row === undefined) {
      problems.push(`${id}: no entry in expectations.json`)
      continue
    }
    if (!Array.isArray(row.verdicts) || row.verdicts.length === 0) {
      problems.push(`${id}: "verdicts" must list at least one verdict`)
      continue
    }
    const unknown = row.verdicts.filter((v) => !ORDER.includes(v))
    if (unknown.length > 0) problems.push(`${id}: unknown verdict ${unknown.join(', ')}`)
    const green = row.verdicts.every((v) => GREEN.includes(v))
    const anyGreen = row.verdicts.some((v) => GREEN.includes(v))
    if (green && row.gap !== undefined) problems.push(`${id}: a green row carries no "gap"`)
    if (!green && anyGreen) {
      problems.push(`${id}: a gap must not allow identical or spelled, or an improvement goes unnoticed`)
    }
    if (!anyGreen && (typeof row.gap !== 'string' || row.gap.trim() === '')) {
      problems.push(`${id}: a row that is not identical or spelled is a documented gap and needs a "gap" reason`)
    }
  }
  const known = new Set(ids)
  for (const id of Object.keys(rows)) if (!known.has(id)) problems.push(`${id}: expectation without a fixture`)
  return problems
}

/** Null when `verdict` is allowed; otherwise what moved, for the failure message. */
export function expectationFailure(id: string, verdict: RowVerdict, row: Expectation): string | null {
  if (row.verdicts.includes(verdict)) return null
  const rank = (v: RowVerdict) => ORDER.indexOf(v)
  const here = rank(verdict)
  let direction = 'unexpected'
  if (here < Math.min(...row.verdicts.map(rank))) direction = 'better than expected: update expectations.json'
  else if (here > Math.max(...row.verdicts.map(rank))) direction = 'worse than expected: a regression'
  return `${id}: ${verdict} (${direction}; allowed ${row.verdicts.join(' | ')})`
}
// The deterministic construct suite (apps/oracle/construct-suite/README.md): Caliper's prop `p` of every fixture against
// the golden TypeScript 7.1's checker gave it, held to the verdict expectations.json allows. The binary is Caliper's own,
// so without one the suite skips; the pure helpers are tested either way.
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync, realpathSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { checkCaliperShape, flattenProps } from '../src/caliper-input.ts'
import {
  expectationFailure,
  expectationProblems,
  listFixtures,
  PROP,
  rowVerdict,
  type Expectation,
  type Golden,
} from '../src/construct-suite.ts'
import { prim } from '../src/oracle-compare.ts'
import { lit } from './lit.ts'

const here = import.meta.dirname
const suite = realpathSync(join(here, '..', 'construct-suite'))
const bin = resolve(process.env.CALIPER_BIN ?? join(here, '..', '..', '..', 'target', 'release', 'caliper-docgen'))
const available = existsSync(bin)
if (!available) {
  console.warn(
    `construct suite skipped: no caliper binary at ${bin}. Build one (cargo build --release -p caliper-docgen) ` +
      'or point CALIPER_BIN at it.',
  )
}

const goldenOf = (checker: Golden['checker']): Golden => ({ checker, text: '' })
const expectations: { rows: Record<string, Expectation> } = JSON.parse(
  readFileSync(join(suite, 'expectations.json'), 'utf8'),
)

describe('the construct suite helpers', () => {
  it('a degraded prop that is only less precise is an opaque type with a marker', () => {
    expect.hasAssertions()
    const golden = goldenOf(prim('string'))
    expect(rowVerdict({ type: { kind: 'string' } }, golden)).toBe('identical')
    expect(rowVerdict({ type: { kind: 'opaque' } }, golden)).toBe('less precise')
    expect(rowVerdict({ type: { kind: 'opaque' }, degradedBy: ['conditionalType'] }, golden)).toBe('opaque with marker')
    expect(rowVerdict({ type: { kind: 'opaque' }, degradedBy: [] }, golden)).toBe('less precise')
  })

  it('a marker does not excuse a wrong type, and a missing prop is its own verdict', () => {
    expect.hasAssertions()
    const golden = goldenOf(prim('string'))
    expect(rowVerdict({ type: { kind: 'number' }, degradedBy: ['conditionalType'] }, golden)).toBe('wrong')
    expect(rowVerdict(undefined, golden)).toBe('missing')
    expect(rowVerdict({ type: { kind: 'stringLiteral', value: 'a' } }, goldenOf(lit('a', 'string')))).toBe('identical')
  })

  it('the expectations must cover the fixtures, with a reason on every gap and no gap that hides an improvement', () => {
    expect.hasAssertions()
    const rows: Record<string, Expectation> = {
      'a/01-ok': { verdicts: ['identical', 'spelled'] },
      'a/02-gap': { verdicts: ['less precise'], gap: 'unevaluated' },
      'a/03-no-reason': { verdicts: ['wrong'] },
      'a/04-hides': { verdicts: ['less precise', 'identical'], gap: 'x' },
      'a/05-green-with-gap': { verdicts: ['identical'], gap: 'x' },
      'a/99-orphan': { verdicts: ['identical'] },
    }
    const ids = ['a/01-ok', 'a/02-gap', 'a/03-no-reason', 'a/04-hides', 'a/05-green-with-gap', 'a/06-unlisted']
    const problems = expectationProblems(ids, rows)
    expect(problems).toHaveLength(5)
    expect(problems.join('\n')).toContain('a/03-no-reason: a row that is not identical or spelled')
    expect(problems.join('\n')).toContain('a/04-hides: a gap must not allow')
    expect(problems.join('\n')).toContain('a/05-green-with-gap: a green row carries no "gap"')
    expect(problems.join('\n')).toContain('a/06-unlisted: no entry')
    expect(problems.join('\n')).toContain('a/99-orphan: expectation without a fixture')
  })

  it('a row better or worse than its expectation fails, and says which way', () => {
    expect.hasAssertions()
    const gap: Expectation = { verdicts: ['less precise'], gap: 'unevaluated' }
    const green: Expectation = { verdicts: ['identical', 'spelled'] }
    expect(expectationFailure('r', 'less precise', gap)).toBeNull()
    expect(expectationFailure('r', 'spelled', green)).toBeNull()
    expect(expectationFailure('r', 'identical', gap)).toContain('better than expected')
    expect(expectationFailure('r', 'opaque with marker', gap)).toContain('better than expected')
    expect(expectationFailure('r', 'wrong', gap)).toContain('worse than expected')
    expect(expectationFailure('r', 'less precise', green)).toContain('worse than expected')
  })

  it('the expectations file agrees with the fixtures on disk', () => {
    expect.hasAssertions()
    const ids = listFixtures(suite).map((f) => f.id)
    expect(expectationProblems(ids, expectations.rows)).toStrictEqual([])
  })

  it('every fixture has a golden', () => {
    expect.hasAssertions()
    const missing = listFixtures(suite).filter((f) => !existsSync(f.golden))
    expect(missing.map((f) => f.id)).toStrictEqual([])
  })
})

describe.skipIf(!available)('the construct suite against the caliper binary', () => {
  it('every row has the verdict expectations.json allows', () => {
    expect.hasAssertions()
    // The addon's options (docs/measurement.md), with a cold cache so the run does not depend on one.
    const stdout = execFileSync(
      bin,
      [
        'extract',
        '--src',
        suite,
        '--json',
        '--html-attributes',
        'full',
        '--include-unexported',
        '--load-dependencies',
        '--collapse-inherited-props',
        'none',
        '--no-cache',
        '--quiet',
      ],
      { encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 },
    )
    const caliper = JSON.parse(stdout)
    checkCaliperShape(caliper)
    const propByFile = new Map<string, any>()
    for (const [key, component] of Object.entries<any>(caliper.components)) {
      if (component.displayName !== 'Row') continue
      const id = flattenProps(caliper, key, component)[PROP]
      propByFile.set(realpathSync(component.filePath), id === undefined ? undefined : caliper.props[id])
    }

    const failures: string[] = []
    for (const fixture of listFixtures(suite)) {
      const golden: Golden = JSON.parse(readFileSync(fixture.golden, 'utf8'))
      const verdict = rowVerdict(propByFile.get(realpathSync(fixture.file)), golden)
      const row = expectations.rows[fixture.id]
      const failure = row && expectationFailure(fixture.id, verdict, row)
      if (failure) failures.push(failure)
    }
    expect(failures).toStrictEqual([])
  })
})

