import { dirname, join } from 'node:path'
const root = process.argv[2]
const dir = '/tmp/claude-501/construct-gen'
const files = ['lit', 'obj', 'util', 'react', 'gen']
const ROW_SEMI = 'export function Row(props: Props) {\n  return null;\n}\n'
const ROW = 'export function Row(props: Props) {\n  return null\n}\n'
let n = 0
for (const f of files) {
  const text = readFileSync(join(dir, f + '.txt'), 'utf8')
  const blocks = text.split(/^=== /m).filter(Boolean)
  for (const b of blocks) {
    const nl = b.indexOf('\n')
    const [style, id] = b.slice(0, nl).split(' ')
    let body = b.slice(nl + 1)
    let out
    if (style === 'RAW') out = body
    else {
      const lines = body.replace(/\n$/, '').split('\n')
      const comment = lines.shift()
      let pi = -1
      lines.forEach((l, i) => { if (/^(readonly )?p\??:/.test(l)) pi = i })
      const pre = lines.slice(0, pi)
      const prop = lines.slice(pi).join('\n')
      const head = `// construct: ${comment}\n`
      if (style === 'L' || style === 'R') {
        const imp = 'import type * as React from "react";\n\n'
        const iface = (style === 'L' ? 'export interface' : 'interface') + ` Props {\n  ${prop}\n}\n\n`
        out = head + imp + (pre.length ? pre.join('\n') + '\n\n' : '') + iface + ROW_SEMI
      } else if (style === 'O') {
        out = head + pre.map((l) => l + '\n').join('') + `interface Props {\n  ${prop}\n}\n` + ROW
      } else if (style === 'U') {
        out = head + pre.map((l) => l + '\n').join('') + `interface Props { ${prop} }\nexport function Row(props: Props) { return null }\n`
      } else throw new Error(style)
    }
    const path = join(root, id + '.tsx')
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, out)
    n++
  }
}
console.log(n)

