import { execFileSync } from 'node:child_process'
import { readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { flattenProps } from './caliper-input.ts'
import { listFixtures, PROP, rowVerdict } from './construct-suite.ts'

const suite = realpathSync(join(import.meta.dirname, '..', 'construct-suite'))
const bin = process.env.CALIPER_BIN!
const stdout = execFileSync(
  bin,
  ['extract', '--src', suite, '--json', '--html-attributes', 'full', '--include-unexported', '--load-dependencies', '--collapse-inherited-props', 'none', '--no-cache', '--quiet'],
  { encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 },
)
const caliper = JSON.parse(stdout)
const propByFile = new Map<string, any>()
for (const [key, component] of Object.entries<any>(caliper.components)) {
  if (component.displayName !== 'Row') continue
  const id = flattenProps(caliper, key, component)[PROP]
  propByFile.set(realpathSync(component.filePath), id === undefined ? undefined : caliper.props[id])
}
const out: any[] = []
for (const f of listFixtures(suite)) {
  const golden = JSON.parse(readFileSync(f.golden, 'utf8'))
  const prop = propByFile.get(realpathSync(f.file))
  out.push({ id: f.id, verdict: rowVerdict(prop, golden), golden: golden.text, caliper: prop?.type, degradedBy: prop?.degradedBy, diag: prop?.diagnostics })
}
writeFileSync(process.argv[2]!, JSON.stringify(out, null, 1))

